CREATE TABLE departments (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE categories (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL UNIQUE,department_id INT UNSIGNED NOT NULL,confidential BOOLEAN NOT NULL DEFAULT FALSE,emergency BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE users (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('Student','Faculty','Staff','Campus Incharge','Department Officer','Administrator') NOT NULL DEFAULT 'Student',department_id INT UNSIGNED NULL,contact_number VARCHAR(30) NULL,affiliation VARCHAR(160) NULL,photo_key TEXT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,email_verified BOOLEAN NOT NULL DEFAULT FALSE,failed_logins INT NOT NULL DEFAULT 0,locked_until DATETIME(3) NULL,auth_version INT NOT NULL DEFAULT 0,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),FOREIGN KEY(department_id) REFERENCES departments(id),CONSTRAINT officer_department CHECK(role <> 'Department Officer' OR department_id IS NOT NULL),INDEX idx_users_role(role,active));
CREATE TABLE auth_tokens (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,kind ENUM('verify','reset') NOT NULL,expires_at DATETIME(3) NOT NULL,used_at DATETIME(3) NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE settings (key_name VARCHAR(100) PRIMARY KEY,value_json JSON NOT NULL);
CREATE TABLE email_templates (event VARCHAR(100) PRIMARY KEY,subject VARCHAR(255) NOT NULL,body TEXT NOT NULL);
CREATE TABLE reference_sequences (date_key CHAR(8) PRIMARY KEY,last_number INT UNSIGNED NOT NULL);
CREATE TABLE complaints (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,reference VARCHAR(30) NOT NULL UNIQUE,reporter_id INT UNSIGNED NOT NULL,category_id INT UNSIGNED NOT NULL,department_id INT UNSIGNED NULL,status ENUM('Submitted','Verified','Assigned','In Progress','Resolved','Returned','Rejected') NOT NULL DEFAULT 'Submitted',priority ENUM('Low','Medium','High','Critical') NOT NULL DEFAULT 'Medium',description TEXT NOT NULL,location VARCHAR(255) NOT NULL,anonymous BOOLEAN NOT NULL DEFAULT FALSE,confidential BOOLEAN NOT NULL DEFAULT FALSE,emergency BOOLEAN NOT NULL DEFAULT FALSE,cycle_number INT NOT NULL DEFAULT 1,version INT NOT NULL DEFAULT 0,resolution_summary TEXT NULL,resolved_at DATETIME(3) NULL,deleted_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),FOREIGN KEY(reporter_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(department_id) REFERENCES departments(id),INDEX idx_complaints_reporter(reporter_id,created_at),INDEX idx_complaints_queue(department_id,status,priority,created_at),INDEX idx_complaints_filter(category_id,status,created_at),INDEX idx_complaints_date(created_at));
CREATE TABLE resolution_cycles (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,complaint_id BIGINT UNSIGNED NOT NULL,cycle_number INT NOT NULL,department_id INT UNSIGNED NULL,started_at DATETIME(3) NOT NULL,sla_hours DECIMAL(8,2) NOT NULL,due_at DATETIME(3) NOT NULL,resolved_at DATETIME(3) NULL,ended_at DATETIME(3) NULL,escalated_at DATETIME(3) NULL,UNIQUE(complaint_id,cycle_number),FOREIGN KEY(complaint_id) REFERENCES complaints(id),FOREIGN KEY(department_id) REFERENCES departments(id),INDEX idx_cycles_due(ended_at,escalated_at,due_at));
CREATE TABLE status_history (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,complaint_id BIGINT UNSIGNED NOT NULL,from_status VARCHAR(30) NULL,to_status VARCHAR(30) NOT NULL,actor_id INT UNSIGNED NULL,actor_role VARCHAR(40) NOT NULL,note TEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(complaint_id) REFERENCES complaints(id),FOREIGN KEY(actor_id) REFERENCES users(id),INDEX idx_history_complaint(complaint_id,created_at));
CREATE TABLE assignments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,complaint_id BIGINT UNSIGNED NOT NULL,from_department_id INT UNSIGNED NULL,department_id INT UNSIGNED NOT NULL,actor_id INT UNSIGNED NULL,actor_role VARCHAR(40) NOT NULL,reason TEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(complaint_id) REFERENCES complaints(id),FOREIGN KEY(from_department_id) REFERENCES departments(id),FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE progress_notes (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,complaint_id BIGINT UNSIGNED NOT NULL,actor_id INT UNSIGNED NOT NULL,actor_role VARCHAR(40) NOT NULL,note TEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(complaint_id) REFERENCES complaints(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE attachments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,complaint_id BIGINT UNSIGNED NOT NULL,storage_key VARCHAR(500) NOT NULL,driver ENUM('local','cloudinary') NOT NULL,mime VARCHAR(80) NOT NULL,size INT UNSIGNED NOT NULL,original_name VARCHAR(255) NOT NULL,kind ENUM('report','proof') NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(complaint_id) REFERENCES complaints(id));
CREATE TABLE feedback (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,complaint_id BIGINT UNSIGNED NOT NULL UNIQUE,reporter_id INT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,comment TEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(complaint_id) REFERENCES complaints(id),FOREIGN KEY(reporter_id) REFERENCES users(id),CONSTRAINT feedback_rating CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE notifications (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,complaint_id BIGINT UNSIGNED NULL,title VARCHAR(255) NOT NULL,body TEXT NOT NULL,event_key VARCHAR(190) NOT NULL UNIQUE,read_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(complaint_id) REFERENCES complaints(id),INDEX idx_notifications_user(user_id,created_at));
CREATE TABLE email_outbox (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,event VARCHAR(100) NOT NULL,variables JSON NOT NULL,event_key VARCHAR(190) NOT NULL UNIQUE,attempts INT NOT NULL DEFAULT 0,available_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),locked_until DATETIME(3) NULL,sent_at DATETIME(3) NULL,last_error VARCHAR(500) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_outbox_pending(sent_at,available_at,locked_until));
CREATE TABLE audit_events (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,actor_id INT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100) NOT NULL,entity_id BIGINT UNSIGNED NULL,metadata JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(actor_id) REFERENCES users(id),INDEX idx_audit_created(created_at));
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Audit events are immutable';
CREATE TRIGGER audit_retention BEFORE DELETE ON audit_events FOR EACH ROW BEGIN IF OLD.created_at > DATE_SUB(UTC_TIMESTAMP(), INTERVAL 12 MONTH) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Audit retention is twelve months'; END IF; END;
CREATE TRIGGER history_no_update BEFORE UPDATE ON status_history FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Status history is immutable';
CREATE TRIGGER history_no_delete BEFORE DELETE ON status_history FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Status history is immutable';
CREATE TRIGGER complaints_no_delete BEFORE DELETE ON complaints FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Complaints must never be physically deleted';
